begin;

alter table public.meal_templates
  add column if not exists purpose text not null default 'pre_workout',
  add column if not exists recovery_categories text[] not null default '{}',
  add column if not exists cuisine_category text,
  add column if not exists meal_type text,
  add column if not exists preparation_difficulty text,
  add column if not exists is_portion_scalable boolean not null default true,
  add column if not exists primary_carb_food_id text,
  add column if not exists primary_protein_food_id text;

alter table public.meal_templates drop constraint if exists meal_templates_purpose_valid;
alter table public.meal_templates add constraint meal_templates_purpose_valid
  check (purpose in ('pre_workout', 'intra_workout', 'post_workout'));

create index if not exists meal_templates_purpose_idx on public.meal_templates (purpose, is_verified);
create index if not exists meal_templates_recovery_categories_idx on public.meal_templates using gin (recovery_categories);

