insert into public.foods (
  source_id, source_product_id, name, category, carb_speed_tier_id, carb_speed_confidence,
  carb_speed_reason, calories_per_100g, carbs_per_100g, protein_per_100g,
  fat_per_100g, fiber_per_100g, data_quality_score, is_verified
)
select 'strictly', source_product_id, name, category, tier, 84,
  'Curated whole-food recovery ingredient.', calories, carbs, protein, fat, fiber, 86, true
from recovery_foods
on conflict (source_id, source_product_id) do update set
  name=excluded.name, category=excluded.category, carb_speed_tier_id=excluded.carb_speed_tier_id,
  calories_per_100g=excluded.calories_per_100g, carbs_per_100g=excluded.carbs_per_100g,
  protein_per_100g=excluded.protein_per_100g, fat_per_100g=excluded.fat_per_100g,
  fiber_per_100g=excluded.fiber_per_100g, data_quality_score=excluded.data_quality_score,
  is_verified=true, updated_at=now();

with recovery_foods(source_product_id, serving_grams, serving_label) as (
  values
    ('recovery:chicken-thigh',142,'5 oz'),('recovery:lean-ground-beef',142,'5 oz'),
    ('recovery:sirloin-steak',142,'5 oz'),('recovery:turkey-breast',142,'5 oz'),
    ('recovery:whole-eggs',100,'2 eggs'),('recovery:salmon',142,'5 oz'),
    ('recovery:tuna',120,'1 can'),('recovery:cottage-cheese',220,'1 cup'),
    ('recovery:firm-tofu',170,'6 oz'),('recovery:black-beans',172,'1 cup'),
    ('recovery:lentils',198,'1 cup'),('recovery:broccoli',120,'1 cup'),
    ('recovery:mixed-vegetables',150,'1 cup'),('recovery:spinach',90,'1/2 cup'),
    ('recovery:salsa',60,'1/4 cup'),('recovery:tomato-sauce',125,'1/2 cup'),
    ('recovery:parmesan',15,'2 tbsp'),('recovery:avocado',75,'1/2 avocado'),
    ('recovery:olive-oil',14,'1 tbsp'),('recovery:corn-tortillas',52,'2 tortillas'),
    ('recovery:wholegrain-bread',80,'2 slices')
)
insert into public.food_portions (food_id,label,amount,unit,gram_weight,is_default,source_description)
select f.id, rf.serving_label, 1, 'serving', rf.serving_grams, true, 'Strictly curated recovery serving'
from recovery_foods rf
join public.foods f on f.source_id='strictly' and f.source_product_id=rf.source_product_id
on conflict (food_id,label,amount,unit) do update
set gram_weight=excluded.gram_weight, is_default=true, source_description=excluded.source_description;

