lable":true,"minGrams":180,"maxGrams":350,"incrementGrams":40},{"foodId":"oats","grams":300,"role":"carb","scalable":true,"minGrams":180,"maxGrams":520,"incrementGrams":40},{"foodId":"banana","grams":118,"role":"produce","scalable":false},{"foodId":"strictly-blueberries","grams":100,"role":"produce","scalable":false},{"foodId":"maple-syrup","grams":15,"role":"topping","scalable":false}],"instructions":["Prepare the oats until soft.","Add cottage cheese, banana, berries, and maple syrup."],"prep_minutes":8,"preparation_difficulty":"easy","cuisine_category":"Breakfast","meal_type":"breakfast","dietary_tags":["vegetarian","halal"],"allergens":["dairy","gluten"],"activity_types":["running","trail_running","cycling","indoor_cycling","mountain_biking","swimming","rowing","triathlon","ironman_70_3","ironman","strength","strength_training","bodybuilding","powerlifting","crossfit","hyrox","hiit","soccer","basketball","general_cardio","mixed_training","endurance"],"recovery_categories":["post_workout_light","post_workout_standard","post_workout_high_demand"],"primary_carb_food_id":"oats","primary_protein_food_id":"cottage-cheese","is_portion_scalable":true},{"slug":"strictly-post-egg-rice-bowl","name":"Egg & Rice Breakfast Bowl","description":"Eggs over rice with spinach, salsa, and avocado.","ingredients":[{"foodId":"whole-eggs","grams":150,"role":"protein","scalable":true,"minGrams":100,"maxGrams":250,"incrementGrams":50},{"foodId":"white-rice","grams":240,"role":"carb","scalable":true,"minGrams":120,"maxGrams":480,"incrementGrams":40},{"foodId":"spinach","grams":90,"role":"produce","scalable":false},{"foodId":"salsa","grams":60,"role":"topping","scalable":false},{"foodId":"avocado","grams":40,"role":"fat","scalable":false}],"instructions":["Warm the rice and spinach.","Top with cooked eggs, salsa, and avocado."],"prep_minutes":15,"preparation_difficulty":"easy","cuisine_category":"Breakfast","meal_type":"breakfast","dietary_tags":["vegetarian","halal","dairy-free","gluten-free"],"allergens":["eggs"],"activity_types":["running","trail_running","cycling","indoor_cycling","mountain_biking","swimming","rowing","triathlon","ironman_70_3","ironman","strength","strength_training","bodybuilding","powerlifting","crossfit","hyrox","hiit","soccer","basketball","general_cardio","mixed_training","endurance"],"recovery_categories":["post_workout_standard","post_workout_high_demand"],"primary_carb_food_id":"white-rice","primary_protein_food_id":"whole-eggs","is_portion_scalable":true}]$recipes$::jsonb) as r(
    slug text, name text, description text, ingredients jsonb, instructions jsonb,
    prep_minutes integer, preparation_difficulty text, cuisine_category text, meal_type text,
    dietary_tags jsonb, allergens jsonb, activity_types jsonb, recovery_categories jsonb,
    primary_carb_food_id text, primary_protein_food_id text, is_portion_scalable boolean
  )
)
insert into public.meal_templates (
  slug,name,description,prep_minutes,instructions,dietary_tags,allergens,activity_types,
  ideal_timing_minutes,timing_low_minutes,timing_high_minutes,min_workout_minutes,
  ingredient_blueprint,is_verified,purpose,recovery_categories,cuisine_category,meal_type,
  preparation_difficulty,is_portion_scalable,primary_carb_food_id,primary_protein_food_id
)
select
  slug,name,description,prep_minutes,
  array(select jsonb_array_elements_text(instructions)),
  array(select jsonb_array_elements_text(dietary_tags)),
  array(select jsonb_array_elements_text(allergens)),
  array(select jsonb_array_elements_text(activity_types)),
  60,30,120,0,ingredients,true,'post_workout',
  array(select jsonb_array_elements_text(recovery_categories)),
  cuisine_category,meal_type,preparation_difficulty,is_portion_scalable,
  primary_carb_food_id,primary_protein_food_id
from recipes
on conflict (slug) do update set
  name=excluded.name,description=excluded.description,prep_minutes=excluded.prep_minutes,
  instructions=excluded.instructions,dietary_tags=excluded.dietary_tags,allergens=excluded.allergens,
  activity_types=excluded.activity_types,ingredient_blueprint=excluded.ingredient_blueprint,
  is_verified=true,purpose='post_workout',recovery_categories=excluded.recovery_categories,
  cuisine_category=excluded.cuisine_category,meal_type=excluded.meal_type,
  preparation_difficulty=excluded.preparation_difficulty,is_portion_scalable=excluded.is_portion_scalable,
  primary_carb_food_id=excluded.primary_carb_food_id,primary_protein_food_id=excluded.primary_protein_food_id,
  updated_at=now();

delete from public.meal_template_items
where template_id in (select id from public.meal_templates where purpose='post_workout');

insert into public.meal_template_items (
  template_id,position,food_id,food_name_snapshot,grams,serving_note,is_scalable
)
select mt.id, ingredient.ordinality::smallint, f.id, coalesce(f.name, ingredient.value->>'foodId'),
  (ingredient.value->>'grams')::numeric, ingredient.value->>'role',
  coalesce((ingredient.value->>'scalable')::boolean,false)
from public.meal_templates mt
cross join lateral jsonb_array_elements(mt.ingredient_blueprint) with ordinality as ingredient(value,ordinality)
left join public.foods f
  on f.source_id='strictly'
 and f.source_product_id in (
   'starter:'||(ingredient.value->>'foodId'),
   'library:'||regexp_replace(ingredient.value->>'foodId','^strictly-',''),
   'recovery:'||(ingredient.value->>'foodId')
 )
where mt.purpose='post_workout';

with totals as (
  select mti.template_id,
    sum(f.calories_per_100g*mti.grams/100) calories,
    sum(f.carbs_per_100g*mti.grams/100) carbs,
    sum(f.protein_per_100g*mti.grams/100) protein,
    sum(f.fat_per_100g*mti.grams/100) fat,
    sum(f.fiber_per_100g*mti.grams/100) fiber,
    sum(case when f.carb_speed_tier_id='fast' then f.carbs_per_100g*mti.grams/100 else 0 end) fast,
    sum(case when f.carb_speed_tier_id='medium' then f.carbs_per_100g*mti.grams/100 else 0 end) medium,
    sum(case when f.carb_speed_tier_id='slow' then f.carbs_per_100g*mti.grams/100 else 0 end) slow
  from public.meal_template_items mti
  join public.foods f on f.id=mti.food_id
  group by mti.template_id
)
update public.meal_templates mt set
  calories=round(t.calories,2),carbs_g=round(t.carbs,2),protein_g=round(t.protein,2),
  fat_g=round(t.fat,2),fiber_g=round(t.fiber,2),fast_carbs_g=round(t.fast,2),
  medium_carbs_g=round(t.medium,2),slow_carbs_g=round(t.slow,2),updated_at=now()
from totals t where mt.id=t.template_id;

commit;
